<script>
document.addEventListener('DOMContentLoaded',()=>{const buttons=[...document.querySelectorAll('#asset360-tabs [data-tab]')],panes=[...document.querySelectorAll('.a360 .pane')];function openTab(name,scroll=true){buttons.forEach(b=>b.classList.toggle('active',b.dataset.tab===name));panes.forEach(p=>p.classList.toggle('active',p.id==='pane-'+name));history.replaceState(null,'','#'+name);if(scroll)document.getElementById('asset360-tabs')?.scrollIntoView({behavior:'smooth',block:'start'});}buttons.forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.tab,false)));document.querySelectorAll('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>openTab(b.dataset.openTab)));const requested=location.hash.slice(1);openTab(buttons.some(b=>b.dataset.tab===requested)?requested:'overview',false);});
</script>
